import{_ as o,o as t,c as a,a0 as d}from"./chunks/framework.DoRPXVp_.js";const h=JSON.parse('{"title":"Apple 端（macOS / iOS）加入网络与登录流程改版设计","description":"","frontmatter":{},"headers":[],"relativePath":"design/apple-join-and-login.md","filePath":"design/apple-join-and-login.md"}'),i={name:"design/apple-join-and-login.md"};function n(c,e,l,s,r,p){return t(),a("div",null,[...e[0]||(e[0]=[d(`<h1 id="apple-端-macos-ios-加入网络与登录流程改版设计" tabindex="-1">Apple 端（macOS / iOS）加入网络与登录流程改版设计 <a class="header-anchor" href="#apple-端-macos-ios-加入网络与登录流程改版设计" aria-label="Permalink to &quot;Apple 端（macOS / iOS）加入网络与登录流程改版设计&quot;">​</a></h1><ul><li><strong>状态</strong>：提议中</li><li><strong>日期</strong>：2026-09-19</li><li><strong>范围</strong>：<code>apple/</code> 下的 macOS App（<code>LatticeMac</code>）与 iOS App（<code>Lattice</code>），以及它们共用的 <code>Shared/</code></li><li><strong>关联</strong>：<code>docs/superpowers/specs/2026-05-13-token-system-enhancement-design.md</code>（<code>lattice://join</code> 与登录同时换取入网令牌）、<code>docs/adr/0003-peer-enrollment-approval-and-client-side-keygen.md</code>（入网审批）</li></ul><h2 id="_1-背景与问题" tabindex="-1">1. 背景与问题 <a class="header-anchor" href="#_1-背景与问题" aria-label="Permalink to &quot;1. 背景与问题&quot;">​</a></h2><p>现在要让一台 Mac 或 iPhone 真正用起来，需要走两套互不相干的流程、填两套凭据：</p><table tabindex="0"><thead><tr><th>流程</th><th>入口</th><th>要填什么</th><th>做什么用</th></tr></thead><tbody><tr><td>加入网络</td><td>mac：<code>ContentView.swift</code> 的 <code>JoinView</code>；iOS：<code>Lattice/JoinView.swift</code></td><td>服务器地址、入网令牌、设备名</td><td>让这台设备成为网络里的一个节点（隧道）</td></tr><tr><td>管理登录</td><td>mac：<code>ContentView.swift</code> 的 <code>SettingsView</code>；iOS：<code>Lattice/LoginView.swift</code></td><td>服务器地址、用户名、密码</td><td>查看和管理节点（列表、改名、下线、删除、ACL、出口节点、意图）</td></tr></tbody></table><p>实际使用中的问题：</p><ol><li><strong>要做两次，服务器地址要填两遍</strong>。两个表单读写同一个 <code>lattice.serverURL</code>，但用户仍要在各自的界面里确认一次。</li><li><strong>看节点列表也要先登录</strong>。<code>LatticeAPI.listPeers()</code> 走管理接口 <code>/api/v1/peers/list</code>，没登录就拿不到列表；而隧道进程通过 provider message 回给界面的只有 <code>peerStates</code>（名称到状态的字典）、<code>lastError</code>、<code>publicKey</code>、<code>overlayIP</code>，不含地址等信息。</li><li><strong>状态和原因不清楚</strong>。2026-09-19 联调时，Mac App 因设备名带空格失败，用户看到的一直是&quot;连接中&quot;，真正的原因（<code>record not found</code>、<code>nats connect ... i/o timeout</code>）是靠读隧道日志才定位的。<code>TunnelManager</code> 会轮询隧道回传的 <code>lastError</code>，但这次没有形成用户能看懂的提示。Apple 端代码里也没有&quot;等待管理员批准&quot;这个状态：ADR-0003 开启 <code>RequirePeerApproval</code> 后，新设备会处于 <code>pending</code> 并拿到空网络图，界面上会表现成连不上。</li><li><strong>管理令牌存放不当</strong>。<code>LatticeAPI</code> 把管理令牌 <code>lattice.authToken</code> 放在 <code>UserDefaults</code>（明文），只有密码放在钥匙串。</li><li><strong>邀请链接只被部分利用</strong>。控制台（<code>frontend/src/pages/manage/tokens/index.vue</code>）已经能生成 <code>lattice://join?server=…&amp;token=…</code> 的二维码，<code>JoinPayload</code> 能解析 <code>server</code> 与 <code>token</code>；但 2026-05-13 的设计里约定的 <code>name</code> 参数没有被解析，Mac 端也没有&quot;粘贴链接即加入&quot;的入口，<code>lattice://</code> 也没有注册为 URL scheme，点链接不能直接打开 App。</li></ol><h2 id="_2-目标与非目标" tabindex="-1">2. 目标与非目标 <a class="header-anchor" href="#_2-目标与非目标" aria-label="Permalink to &quot;2. 目标与非目标&quot;">​</a></h2><p>目标：</p><ul><li>入网是<strong>唯一必须的一步</strong>，新设备从打开 App 到连上网络，只需要一次输入（粘贴链接、扫码，或在有账号时登录）。</li><li>主界面不需要登录就能看到节点、IP、连接方式（直连或中继）。</li><li>只有真正的管理操作才要求登录，登录一次后不再反复询问。</li><li>任何失败都给出原因和下一步建议，而不是一直&quot;连接中&quot;。</li><li>macOS 与 iOS 的流程和文案一致，只有输入方式不同（iOS 扫码，Mac 粘贴或拖入）。</li></ul><p>非目标：SSO（按既有决定暂缓，入口保持现状）、改动服务器 API 语义（除第 6 节提到需要确认的两点）、UI 视觉风格重做。</p><h2 id="_3-设计原则-两类凭据-各管各的" tabindex="-1">3. 设计原则：两类凭据，各管各的 <a class="header-anchor" href="#_3-设计原则-两类凭据-各管各的" aria-label="Permalink to &quot;3. 设计原则：两类凭据，各管各的&quot;">​</a></h2><ul><li><strong>设备凭据</strong>：入网令牌。作用是让设备注册并建立隧道。放在 VPN 配置的 <code>providerConfiguration</code> 里（<code>TunnelManager.createProfile</code>），由隧道进程使用。用户只在入网时接触它。</li><li><strong>管理凭据</strong>：账号密码，换来的管理令牌用于调用管理 API。只在用户要做管理操作时才需要。</li></ul><p>这两类凭据不应该再在界面上并列出现。入网流程只碰前者；后者只在被需要的那一刻才出现。</p><h2 id="_4-新流程" tabindex="-1">4. 新流程 <a class="header-anchor" href="#_4-新流程" aria-label="Permalink to &quot;4. 新流程&quot;">​</a></h2><h3 id="_4-1-状态机" tabindex="-1">4.1 状态机 <a class="header-anchor" href="#_4-1-状态机" aria-label="Permalink to &quot;4.1 状态机&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>未加入 ──输入链接/令牌──► 入网中 ──注册成功──► 已获批? ──否──► 等待批准</span></span>
<span class="line"><span>                          │                       │是           │批准后</span></span>
<span class="line"><span>                          ▼                       ▼             ▼</span></span>
<span class="line"><span>                        失败(带原因)         连接中(协商) ──► 已连接</span></span>
<span class="line"><span>                                               │</span></span>
<span class="line"><span>                                               ▼</span></span>
<span class="line"><span>                                            失败(带原因)</span></span></code></pre></div><p>各状态的界面文案：</p><table tabindex="0"><thead><tr><th>状态</th><th>主文案</th><th>说明与操作</th></tr></thead><tbody><tr><td>未加入</td><td>加入网络</td><td>见 4.2</td></tr><tr><td>入网中</td><td>正在向服务器注册…</td><td>显示服务器地址；可取消</td></tr><tr><td>等待批准</td><td>等待管理员批准</td><td>说明&quot;管理员批准后会自动连接&quot;，显示设备名和公钥指纹，方便管理员核对；可退出网络</td></tr><tr><td>连接中</td><td>正在建立连接…</td><td>显示已连上的节点数；超过 30 s 仍未连上时给出提示和&quot;查看诊断&quot;</td></tr><tr><td>已连接</td><td>已连接 · 10.96.0.x</td><td>节点列表见 4.4</td></tr><tr><td>失败</td><td>显示原因（见下表）与&quot;重试&quot;</td><td>&quot;复制诊断信息&quot;导出隧道日志末尾若干行</td></tr></tbody></table><p>失败原因的归类（根据引擎报出的错误映射，文案是建议）：</p><table tabindex="0"><thead><tr><th>引擎错误特征</th><th>用户看到的原因</th><th>建议</th></tr></thead><tbody><tr><td>服务发现请求失败、超时</td><td>连不上服务器</td><td>检查服务器地址与网络；如在使用代理或 VPN，给服务器地址加直连规则</td></tr><tr><td><code>nats connect … i/o timeout</code></td><td>连不上信令端口（4222）</td><td>同上；确认云安全组放行 4222/tcp</td></tr><tr><td>注册被拒：令牌无效、已过期、次数用完</td><td>入网令牌不可用</td><td>向管理员重新获取邀请链接</td></tr><tr><td>提示需要重新入网（公钥不匹配）</td><td>这台设备的身份与服务器记录不一致</td><td>选择&quot;重新入网&quot;</td></tr><tr><td>注册成功但 <code>pending</code></td><td>见&quot;等待批准&quot;状态</td><td>无</td></tr><tr><td>其他</td><td>原始错误信息</td><td>复制诊断信息</td></tr></tbody></table><h3 id="_4-2-入网入口-一个输入框" tabindex="-1">4.2 入网入口：一个输入框 <a class="header-anchor" href="#_4-2-入网入口-一个输入框" aria-label="Permalink to &quot;4.2 入网入口：一个输入框&quot;">​</a></h3><p>首屏只有一个入口：</p><ul><li><strong>粘贴邀请链接或令牌</strong>：输入框接受完整的 <code>lattice://join?server=…&amp;token=…&amp;name=…</code>，也接受只有令牌的字符串。打开界面时如果剪贴板内容能被 <code>JoinPayload</code> 解析，直接预填并提示&quot;检测到邀请链接&quot;。</li><li><strong>扫码</strong>：iOS 现在首页有&quot;扫描二维码&quot;和&quot;手动输入&quot;两个入口（<code>OverviewView</code> 里用 <code>sheet(item:)</code> 区分模式），合并成上面这个输入框，并在输入框旁保留扫码按钮；Mac 保留现有扫码窗口，并增加拖入二维码图片。</li><li><strong>只有令牌、没有服务器地址时</strong>，才展开&quot;服务器地址&quot;一栏（上次成功的地址作为默认值）。</li><li><strong>设备名</strong>默认取主机名，折叠在&quot;高级&quot;里；名称包含空格时，界面提示&quot;将保存为 <code>MacBook-Pro</code>&quot;，与服务器的规范化结果一致（见 <code>infra.NormalizeAppID</code>）。</li></ul><p><code>JoinPayload</code> 增加可选的 <code>name</code> 参数，其余不变，旧链接继续可用。</p><p>点击&quot;加入&quot;之后，首次会弹出系统的 VPN 配置授权，界面在此之前先给一句说明，避免用户以为是异常。</p><h3 id="_4-3-有账号时-登录即入网-可选路径" tabindex="-1">4.3 有账号时：登录即入网（可选路径） <a class="header-anchor" href="#_4-3-有账号时-登录即入网-可选路径" aria-label="Permalink to &quot;4.3 有账号时：登录即入网（可选路径）&quot;">​</a></h3><p>对有账号的管理员，提供第二个入口&quot;用账号登录并加入&quot;：输入服务器地址、用户名、密码后：</p><ol><li>登录，取得管理令牌与工作区；</li><li>以 <code>X-Workspace-Id</code> 调用 <code>POST /api/v1/token/generate</code>，为这台设备生成一个入网令牌；</li><li>用该令牌走与 4.2 相同的 <code>saveJoin</code>。</li></ol><p>结果是一次输入同时得到设备身份和管理登录状态，之后管理操作不必再登录。这与 2026-05-13 设计里&quot;<code>lattice login</code> 一次认证，同时返回管理令牌与入网令牌&quot;是同一思路。被邀请的普通设备不需要这条路径，仍用 4.2。</p><h3 id="_4-4-节点列表不依赖登录" tabindex="-1">4.4 节点列表不依赖登录 <a class="header-anchor" href="#_4-4-节点列表不依赖登录" aria-label="Permalink to &quot;4.4 节点列表不依赖登录&quot;">​</a></h3><p>主界面的节点列表、状态、IP 直接取自隧道自己的网络图：</p><ul><li>隧道进程（<code>apple/engine</code>）在现有 provider message 之外新增 <code>peers</code> 消息，返回每个节点的名称、地址、传输方式（直连、中继、协商中、离线）、最近握手时间。数据来源直接复用 <code>Node.StatusSnapshot</code>（<code>lattice status</code> 用的同一份，见 <code>internal/agent/status_peers.go</code>）。</li><li>已登录时，再用管理 API 的数据补充显示名、标签、下线状态、通告路由、最近在线时间等增强字段，按节点名称合并。</li><li>未登录时，这些增强字段不显示，也不再弹出&quot;请先登录&quot;的整页错误。</li></ul><h3 id="_4-5-管理操作按需登录" tabindex="-1">4.5 管理操作按需登录 <a class="header-anchor" href="#_4-5-管理操作按需登录" aria-label="Permalink to &quot;4.5 管理操作按需登录&quot;">​</a></h3><p>改名、下线、删除、ACL、出口节点、意图这类操作，点击时如果没有有效的管理令牌：</p><ol><li>弹出&quot;登录以管理&quot;的面板，服务器地址已预填，用户名带出上次使用的；</li><li>登录成功后自动继续刚才的操作；</li><li>凭据存钥匙串，管理令牌过期（7 天）时沿用现在的静默重新登录（<code>LatticeAPI.relogin</code>）。</li></ol><p>管理令牌从 <code>UserDefaults</code> 迁移到钥匙串，读到旧值时迁移一次并删除旧键。</p><h2 id="_5-界面草图" tabindex="-1">5. 界面草图 <a class="header-anchor" href="#_5-界面草图" aria-label="Permalink to &quot;5. 界面草图&quot;">​</a></h2><p>首屏（未加入）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌────────────────────────────────────────┐</span></span>
<span class="line"><span>│  加入网络                                │</span></span>
<span class="line"><span>│                                          │</span></span>
<span class="line"><span>│  ┌────────────────────────────────────┐ │</span></span>
<span class="line"><span>│  │ 粘贴邀请链接或令牌                    │ │</span></span>
<span class="line"><span>│  └────────────────────────────────────┘ │</span></span>
<span class="line"><span>│   检测到剪贴板中的邀请链接  [使用]          │</span></span>
<span class="line"><span>│                                          │</span></span>
<span class="line"><span>│  [扫码加入]          [用账号登录并加入]    │</span></span>
<span class="line"><span>│                                          │</span></span>
<span class="line"><span>│  ▸ 高级（服务器地址、设备名）               │</span></span>
<span class="line"><span>│                    [ 加入 ]              │</span></span>
<span class="line"><span>└────────────────────────────────────────┘</span></span></code></pre></div><p>失败：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌────────────────────────────────────────┐</span></span>
<span class="line"><span>│  ⚠ 连不上信令端口（4222）                 │</span></span>
<span class="line"><span>│  检查网络或代理设置；如果使用代理，请给      │</span></span>
<span class="line"><span>│  服务器地址添加直连规则。                  │</span></span>
<span class="line"><span>│  [重试]  [复制诊断信息]  [退出网络]         │</span></span>
<span class="line"><span>└────────────────────────────────────────┘</span></span></code></pre></div><h2 id="_6-需要服务器确认的两点" tabindex="-1">6. 需要服务器确认的两点 <a class="header-anchor" href="#_6-需要服务器确认的两点" aria-label="Permalink to &quot;6. 需要服务器确认的两点&quot;">​</a></h2><ol><li><code>POST /api/v1/token/generate</code> 目前挂在 <code>WorkspaceAuthMiddleware(RoleViewer)</code> 之下，也就是工作区里最低的 Viewer 角色就能生成令牌。4.3 依赖这个接口，是否允许普通成员自助入网，需要产品上确认；如需收紧，4.3 只对管理员开放。</li><li>入网令牌的语义（单次使用、有效期、使用次数上限）以服务器实际实现为准，App 需要把&quot;令牌已用完&quot;和&quot;已过期&quot;分开提示，前提是服务器返回可区分的错误信息。</li></ol><h2 id="_7-兼容与迁移" tabindex="-1">7. 兼容与迁移 <a class="header-anchor" href="#_7-兼容与迁移" aria-label="Permalink to &quot;7. 兼容与迁移&quot;">​</a></h2><ul><li>已入网的设备不受影响，<code>lattice.joined</code> 等既有状态保留。</li><li>旧邀请链接、旧二维码继续可用（<code>name</code> 可选）。</li><li><code>lattice.authToken</code> 迁移到钥匙串（4.5）。</li><li>隧道进程新增的 <code>peers</code> 消息是追加，旧版界面不发这条消息就不受影响。</li></ul><h2 id="_8-实施拆分" tabindex="-1">8. 实施拆分 <a class="header-anchor" href="#_8-实施拆分" aria-label="Permalink to &quot;8. 实施拆分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>内容</th><th>主要文件</th></tr></thead><tbody><tr><td>P1</td><td>入网单输入框；<code>JoinPayload</code> 增加 <code>name</code>；状态与失败原因文案；服务器地址只填一次</td><td><code>Shared/JoinPayload.swift</code>、mac <code>JoinView</code>、iOS <code>Lattice/JoinView.swift</code>、<code>Shared/TunnelManager.swift</code></td></tr><tr><td>P2</td><td>隧道新增 <code>peers</code> 消息；节点列表脱离登录</td><td><code>apple/engine/engine.go</code>、<code>LatticeTunnel*/PacketTunnelProvider.swift</code>、<code>Shared/TunnelManager.swift</code></td></tr><tr><td>P3</td><td>管理操作按需登录；管理令牌迁移到钥匙串</td><td><code>Shared/LatticeAPI.swift</code>、mac <code>SettingsView</code>、iOS <code>LoginView</code></td></tr><tr><td>P4</td><td>用账号登录并加入</td><td><code>Shared/LatticeAPI.swift</code>（新增生成令牌）、两端入网界面</td></tr><tr><td>P5</td><td>&quot;等待批准&quot;状态</td><td>需要引擎把 <code>pending</code> 作为独立事件抛出，见第 9 节第 1 点</td></tr></tbody></table><h2 id="_8-1-p1-实施记录-2026-09-19" tabindex="-1">8.1 P1 实施记录（2026-09-19） <a class="header-anchor" href="#_8-1-p1-实施记录-2026-09-19" aria-label="Permalink to &quot;8.1 P1 实施记录（2026-09-19）&quot;">​</a></h2><p>已实现（macOS 与 iOS）：</p><ul><li>入网只有一个输入框，接受 <code>lattice://join?server=…&amp;token=…&amp;name=…</code> 链接或裸令牌；服务器地址和设备名折叠在&quot;高级&quot;里，输入里没有服务器地址时自动提示并展开。<code>JoinPayload</code> 增加可选的 <code>name</code>，旧链接不受影响。</li><li>设备名带空格等字符时，&quot;高级&quot;里显示&quot;将保存为 …&quot;（<code>DeviceName.normalized</code>，与 Go 的 <code>infra.NormalizeAppID</code> 规则一致）。App 里记录&quot;本机名称&quot;改为规范化后的名字，这样节点列表能认出&quot;这台设备&quot;（原来带空格的名字会对不上）。</li><li>失败原因归类（<code>JoinFailure.classify</code>）：把引擎和服务器的原始报错映射成&quot;原因 + 建议&quot;，在 macOS 主界面和 iOS 概览页显示；无法识别的错误仍显示原文。</li><li>与设计的差别：打开入网界面时只会自动读取剪贴板里<strong>完整的邀请链接</strong>；裸令牌只能点&quot;粘贴&quot;按钮读取，避免把用户复制过的任意单词（比如密码）显示到输入框里。</li></ul><p>验证方式：<code>apple/Scripts/test_apple_logic.sh</code> 编译并运行链接解析、名称规范化、失败归类、节点列表合并的检查（这些代码只依赖 Foundation，不需要 Xcode 测试 target）；两端 App 均已构建通过。界面本身还没有做人工走查。</p><h2 id="_8-2-p2-实施记录-2026-09-19" tabindex="-1">8.2 P2 实施记录（2026-09-19） <a class="header-anchor" href="#_8-2-p2-实施记录-2026-09-19" aria-label="Permalink to &quot;8.2 P2 实施记录（2026-09-19）&quot;">​</a></h2><p>已实现（macOS 与 iOS）：</p><ul><li>引擎新增 <code>Engine.Peers()</code>，返回隧道自己的节点列表 JSON（名称、地址、平台、连接状态、是否在线），数据来自网络图和探测状态，排除本机和还没有地址的节点；构造逻辑是不依赖 gomobile 的纯函数（<code>apple/engine/peers.go</code>，有单测）。</li><li>两个隧道扩展在 <code>peerStates</code> 消息的回复里增加 <code>peers</code> 字段，<code>TunnelManager</code> 解码为 <code>tunnelPeers</code>，只在内容变化时更新，隧道断开时清空。</li><li>节点列表 = 管理 API 数据与隧道数据的合并（<code>PeerListMerge.merged</code>）：两边都有的节点以 API 为准（显示名、标签、路由、停用状态），只有隧道知道的节点追加在后面，没登录时列表完全来自隧道。<code>PeerNode.id</code> 改为稳定的（AppID，缺失时用名称），原来每次重建都会生成新的 UUID，列表每 2 秒被当成全新数据。</li><li>未登录时不再请求管理 API，也不再自动弹出登录页；列表上方是一条&quot;登录后可管理设备&quot;的提示。登录已过期但隧道有数据时同样只提示。</li></ul><p>已知不足：未登录时点节点行上的改名、下线、删除仍会调用管理 API 并报错，这属于 P3（按需登录）。列表里还没有最近握手时间。</p><h2 id="_8-3-p3-实施记录-2026-09-19" tabindex="-1">8.3 P3 实施记录（2026-09-19） <a class="header-anchor" href="#_8-3-p3-实施记录-2026-09-19" aria-label="Permalink to &quot;8.3 P3 实施记录（2026-09-19）&quot;">​</a></h2><p>已实现（macOS 与 iOS）：</p><ul><li><strong>管理令牌迁移到钥匙串</strong>：<code>AuthTokenStore</code> 优先读钥匙串，读到 <code>UserDefaults</code> 里的旧明文令牌时迁移一次，确认钥匙串里确实写进去了才删除旧值（写入失败则保留旧值，令牌仍可用）。写入永远不再留明文副本。存取抽成可注入的接口，用内存假实现做了测试。</li><li><strong>按需登录</strong>：<code>LatticeAPI</code> 里凡是写操作（改名、下线、删除、设置路由、意图、AI 对话等，即非 GET 请求）在没有登录时，会通过 <code>LoginCoordinator</code> 暂停，界面弹出&quot;登录以管理设备&quot;面板，登录成功后自动继续刚才的操作，取消则返回&quot;已取消登录&quot;。同时有多个操作在等，会一起继续。只读请求不弹窗。保存的凭据失效（401 且静默重新登录失败）时，用户发起的操作同样会重新询问。</li><li><strong>面板</strong>：macOS 用紧凑的 <code>ManageLoginView</code>（服务器地址只读显示、用户名带出上次使用的），只在主窗口弹出，菜单栏面板不弹；iOS 复用 <code>LoginView</code>，挂在 <code>RootView</code> 上。设备列表上方的&quot;登录后可管理设备&quot;提示直接打开这个面板。</li><li><strong>登录状态可观察</strong>：新增 <code>AuthSession</code>，替代 iOS 里对 <code>@AppStorage(&quot;lattice.authToken&quot;)</code> 的依赖（令牌进了钥匙串，SwiftUI 观察不到）；登录、退出后列表自动刷新。新增 <code>LatticeAPI.logout()</code>，退出登录、退出网络、重新生成密钥都走它，统一清理令牌、保存的密码和工作区缓存。</li></ul><p>已知不足：节点详情里的只读内容（例如 ACL）未登录时仍会失败并显示错误，没有单独的&quot;登录后查看&quot;提示；设置页里原有的登录表单保留未动。</p><h2 id="_8-4-p4-实施记录-2026-09-19" tabindex="-1">8.4 P4 实施记录（2026-09-19） <a class="header-anchor" href="#_8-4-p4-实施记录-2026-09-19" aria-label="Permalink to &quot;8.4 P4 实施记录（2026-09-19）&quot;">​</a></h2><p>已实现（macOS 与 iOS）：</p><ul><li>入网界面顶部有&quot;邀请链接 / 令牌&quot;和&quot;账号登录&quot;两种方式。账号登录只需要服务器地址、用户名、密码，设备名折叠在&quot;高级&quot;里；按钮是&quot;登录并加入&quot;。</li><li>流程：登录（<code>lattice.serverURL</code> 先写成填的地址）→ 为这台设备生成一个入网令牌（<code>POST /api/v1/token/generate</code>，工作区取登录时解析出的那个）→ 用这个令牌走与邀请链接相同的入网流程。登录状态保留在钥匙串里，之后的管理操作不再需要登录。</li><li>失败会说明是哪一步：登录失败，或登录成功但没能签发令牌；后者对权限不足（服务器返回 <code>Insufficient permissions</code>）给出专门的说明和建议。</li><li>令牌参数：不指定名字（由服务器生成随机令牌；指定名字时令牌值就是这个名字，容易重复也容易猜），使用次数 1，有效期 8760 小时。</li></ul><p><strong>必须记住的一个服务器行为</strong>：注册时服务器先检查令牌是否过期，然后才判断&quot;已有设备重新注册，不受使用次数限制&quot;。而客户端每次启动引擎都会用保存的入网令牌重新注册，所以令牌一旦过期，已经入网的设备下次重新连接就会被拒绝（<code>token is expired</code>）。服务器默认有效期只有 168 小时，这也是 P4 选了一年的原因。测试环境里现有的入网令牌都是默认的 7 天，最早的一批在 2026-09-25 到期，到期后使用它们的设备（云主机上的容器、Mac、手机）重新注册会失败。</p><p><strong>已在服务器上修复</strong>（2026-09-20，提交 <code>a9129475</code>，已部署到测试云主机）：过期检查只对&quot;不是用这个令牌入网的设备&quot;生效。已入网的设备用自己入网时的令牌重新注册，令牌过期后照样能恢复，因为 <code>GetNetmap</code> 本来就无条件接受这个令牌，拒绝注册只会把已入网的设备锁在外面，并不能保护什么；过期的令牌仍然不能让新设备入网，也不能接管别的令牌入网的设备（三种情况都有测试）。现有测试环境的令牌不需要重发。新生成的令牌默认有效期仍是 7 天，它只决定新设备的入网窗口。</p><h2 id="_8-5-p5-实施记录-2026-09-19" tabindex="-1">8.5 P5 实施记录（2026-09-19） <a class="header-anchor" href="#_8-5-p5-实施记录-2026-09-19" aria-label="Permalink to &quot;8.5 P5 实施记录（2026-09-19）&quot;">​</a></h2><p>第 9 节第 1 个问题的答案：<strong>原来没有</strong>。设备被工作区的入网审批（ADR-0003）挂起时，服务器返回的网络图里 <code>Current</code> 带着 <code>approvalStatus: pending</code> 和空地址，但客户端 <code>fetchNetMap</code> 只认&quot;有地址&quot;，等满 60 秒就报&quot;timed out waiting for VPN IP allocation&quot;，界面表现为连接失败。</p><p>已实现（引擎、macOS、iOS）：</p><ul><li><strong>识别</strong>：<code>classifyNetmap</code> 把网络图分成等待分配、待批准、已撤销、就绪四种。待批准时只通知一次（<code>onPending</code>），之后一直等到批准，不再有 60 秒的分配超时（服务器一直有应答就一直等），轮询间隔从 0.5 秒逐步放慢到 15 秒；已撤销返回 <code>ErrDeviceRevoked</code>；没有审批时行为不变，仍然 60 秒超时。取消（停止引擎）会立即结束等待。新增 <code>RegisterSandboxViaNATSNotify</code>，原函数保持不变。</li><li><strong>引擎事件</strong>：待批准时引擎发出 <code>awaiting-approval</code>；批准后继续正常入网，无需用户操作。</li><li><strong>界面</strong>：两个隧道扩展在回复里增加 <code>phase</code>，<code>TunnelManager.awaitingApproval</code> 为真时，<code>lastFailure</code> 是&quot;等待管理员批准 / 管理员批准后会自动连接&quot;，用橙色（提示）而不是红色（错误）显示，macOS 主界面和 iOS 概览页都是；已撤销显示&quot;这台设备已被管理员停用&quot;。</li><li><strong>顺带修复的已有缺陷</strong>：<code>TunnelManager</code> 只在隧道已连接时才轮询隧道进程，代码注释写着&quot;连接中也轮询&quot;，实际没有，所以连接过程中（包括启动失败）界面拿不到任何原因，只能一直显示&quot;连接中&quot;。现在连接中也轮询；同时&quot;隧道进程无响应&quot;的提示只在连接超过 15 秒仍无回应时才出现，避免扩展刚启动时误报。</li></ul><p>验证方式：<code>internal/agent/sandbox_register_test.go</code> 用脚本化的假服务器测试待批准会一直等（超过分配超时）、只通知一次、撤销报错、无审批仍超时、取消能结束等待；Swift 侧有失败文案和提示样式的检查。</p><p><strong>还没有验证的</strong>：真实的审批流程（需要在工作区开启入网审批，用一个新设备加入，看到等待状态，再批准）。一个具体的风险是隧道扩展在等待期间一直没有完成 <code>startTunnel</code>，系统是否会因超时而结束扩展，这一点只能在真机上确认。</p><p>未做：URL scheme 注册（第 9 节第 2 点）。</p><h2 id="_9-待确认的问题" tabindex="-1">9. 待确认的问题 <a class="header-anchor" href="#_9-待确认的问题" aria-label="Permalink to &quot;9. 待确认的问题&quot;">​</a></h2><ol><li>代理侧（<code>internal/agent</code>）遇到 <code>pending</code> 注册响应时，引擎目前是否已经把它作为独立状态抛给上层？如果没有，P5 需要先在引擎里补这个事件。</li><li><code>lattice://</code> 这个 URL scheme 目前在两端的 <code>Info.plist</code> 和 <code>project.yml</code> 里都没有找到注册（没有 <code>CFBundleURLSchemes</code>），所以从浏览器点邀请链接不能直接唤起 App。P1 是否顺带注册并处理 <code>onOpenURL</code>？</li><li>令牌 TTL 与次数上限（第 6 节第 2 点），以及&quot;账号登录并加入&quot;生成的令牌是否应该绑定这台设备、短有效期。</li><li>SSO 恢复后，&quot;用账号登录并加入&quot;是否改为浏览器登录回调（2026-05-13 设计中的 SSO 扫码场景）。</li></ol><h2 id="_10-验证清单" tabindex="-1">10. 验证清单 <a class="header-anchor" href="#_10-验证清单" aria-label="Permalink to &quot;10. 验证清单&quot;">​</a></h2><ul><li>全新安装：粘贴完整链接、只粘贴令牌、扫码，三种方式都能加入；系统 VPN 授权弹出前有说明。</li><li>设备名带空格（如 <code>MacBook Pro</code>）：能加入，界面提示规范化后的名称，节点列表里名称与服务器一致。</li><li>服务器 4222 不通或超时：界面 30 s 内给出&quot;连不上信令端口&quot;和重试，而不是一直&quot;连接中&quot;。</li><li>令牌无效、过期：分别提示。</li><li>开启入网审批：显示&quot;等待管理员批准&quot;，批准后自动连上。</li><li>未登录：能看到节点列表和连接方式；点击改名弹出登录面板，登录后自动完成改名。</li><li>管理令牌过期：静默重新登录，操作不中断。</li><li>旧版本升级后：已入网设备保持连接，管理令牌完成迁移。</li><li>macOS 与 iOS 分别过一遍，文案一致。</li></ul>`,76)])])}const q=o(i,[["render",n]]);export{h as __pageData,q as default};
